package cn.academy.port.maintenance;
import java.io.File;import java.net.*;import java.nio.file.Path;import java.util.*;
public final class ClassicActivationAndSetXpServerLinkTest {
 private static final class ServerLoader extends URLClassLoader {int requests;ServerLoader(URL[] urls){super(urls,ClassLoader.getPlatformClassLoader());}@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(name.startsWith("net.minecraft.client.")||name.startsWith("net.neoforged.neoforge.client.")||name.startsWith("cn.academy.port.client.")){requests++;throw new ClassNotFoundException("server denies "+name);}return super.loadClass(name,resolve);}}
 public static void main(String[] args)throws Exception{var urls=new ArrayList<URL>();for(String path:System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(File.pathSeparator)))urls.add(Path.of(path).toUri().toURL());int checks=0;try(var loader=new ServerLoader(urls.toArray(URL[]::new))){for(String name:List.of("core.AbilityProgress","AbilityConsumption","AcademyGameplay","command.ClassicAbilityCommands","api.AbilityActivationLifecycle","api.AbilityActivateEvent","api.AbilityDeactivateEvent","api.SkillExpChangedEvent","api.AbilityProgressLifecycle","api.AbilityCategoryLifecycle","gametest.AcademyActivationAndSetXpRuntimeTests")){var queue=new ArrayDeque<Class<?>>();queue.add(Class.forName("cn.academy.port."+name,false,loader));while(!queue.isEmpty()){var type=queue.remove();type.getDeclaredConstructors();type.getDeclaredFields();type.getDeclaredMethods();queue.addAll(List.of(type.getDeclaredClasses()));checks++;}}if(loader.requests!=0)throw new AssertionError("Activation/setter API requested client classes");}System.out.println("PASS "+checks+" actual staged common activation/setter/command/lifecycle classes cold linked with all client namespaces denied; no bootstrap");}
}
